import os,re,json
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps(g,bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for di in(-1,0,1):
                        for dj in(-1,0,1):
                            y,x=a+di,b+dj
                            if 0<=y<H and 0<=x<W and g[y][x]!=bg and not seen[y][x]:
                                seen[y][x]=True; st.append((y,x))
                res.append(cells)
    return res
def norm(cells,g):
    mr=min(a for a,b in cells); mc=min(b for a,b in cells)
    return tuple(sorted(((a-mr,b-mc,g[a][b])) for a,b in cells))
def diheds(t):
    out=set(); stack=[tuple(t)]
    while stack:
        q=stack.pop()
        if q in out: continue
        out.add(q); stack.append(tuple(sorted(((b,-a,v) for a,b,v in q))))
        stack.append(tuple(sorted((a,-b,v) for a,b,v in q)))
    return sorted(out)
